[CmdletBinding()]
param()

$ErrorActionPreference = "Stop"
$Root = Resolve-Path (Join-Path $PSScriptRoot "..")
$AuditPath = Join-Path $Root "scripts\audit_artifacts.ps1"
$Text = Get-Content -LiteralPath $AuditPath -Raw

function Assert-Matches {
  param(
    [string]$Pattern,
    [string]$Description
  )
  if ($Text -notmatch $Pattern) {
    throw "Audit official suite validation gate missing: $Description. Pattern: $Pattern"
  }
}

Assert-Matches "--rejectSoftwareRendering" "suite validator software-rendering rejection argument"
Assert-Matches "--rejectGpuInstability" "suite validator GPU-instability rejection argument"
Assert-Matches "--requireGpuMetadata" "suite validator GPU metadata requirement argument"
Assert-Matches "--requireFrameTimes" "suite validator raw frame-time sample requirement argument"
Assert-Matches "--expectedBuildArgsHash" "suite validator expected build-args hash argument"
Assert-Matches "--expectedChromiumRevision" "suite validator expected Chromium revision argument"
Assert-Matches "--expectedBrowser" "suite validator expected browser executable argument"
Assert-Matches "--expectedMeasuredSeconds" "suite validator measured-seconds argument"
Assert-Matches "--expectedWarmupSeconds" "suite validator warmup-seconds argument"
Assert-Matches "--expectedComplexity" "suite validator benchmark complexity argument"
Assert-Matches "--expectedFlagMetadata" "suite validator expected flag metadata argument"
Assert-Matches "Official performance.*Stock WebGL2 scene suite results[\s\S]*-RejectSoftwareRendering[\s\S]*-RejectGpuInstability[\s\S]*-RequireGpuMetadata[\s\S]*-RequireFrameTimes" "stock WebGL2 audit row strict GPU and frame-time validation"
Assert-Matches 'Official performance.*Stock WebGL2 scene suite results[\s\S]*-ExpectedChromiumRevision\s+\$ExpectedChromiumRevision' "stock WebGL2 audit row expected Chromium revision"
Assert-Matches 'Official performance.*Stock WebGL2 scene suite results[\s\S]*-ExpectedBrowser\s+\(Resolve-RepoPath "src\\out\\ReleaseBaseline\\content_shell\.exe"\)' "stock WebGL2 audit row expected browser executable"
Assert-Matches 'Official performance.*Stock WebGL2 scene suite results[\s\S]*-ExpectedBuildArgsHash\s+\$BaselineBuildArgsHash' "stock WebGL2 audit row expected build-args hash"
Assert-Matches 'Official performance.*Stock WebGL2 scene suite results[\s\S]*-ExpectedFlagMetadata\s+\$BrowserModeFlags' "stock WebGL2 audit row browser-mode flag metadata"
Assert-Matches "Official performance.*Fork default WebGL2 scene suite results[\s\S]*-RejectSoftwareRendering[\s\S]*-RejectGpuInstability[\s\S]*-RequireGpuMetadata[\s\S]*-RequireFrameTimes" "fork WebGL2 audit row strict GPU and frame-time validation"
Assert-Matches 'Official performance.*Fork default WebGL2 scene suite results[\s\S]*-ExpectedChromiumRevision\s+\$ExpectedChromiumRevision' "fork WebGL2 audit row expected Chromium revision"
Assert-Matches 'Official performance.*Fork default WebGL2 scene suite results[\s\S]*-ExpectedBrowser\s+\(Resolve-RepoPath "src\\out\\ReleaseViewerDefault\\content_shell\.exe"\)' "fork WebGL2 audit row expected browser executable"
Assert-Matches 'Official performance.*Fork default WebGL2 scene suite results[\s\S]*-ExpectedBuildArgsHash\s+\$ForkBuildArgsHash' "fork WebGL2 audit row expected build-args hash"
Assert-Matches 'Official performance.*Fork default WebGL2 scene suite results[\s\S]*-ExpectedFlagMetadata\s+\$ForkDefaultFlags' "fork WebGL2 audit row viewer flag metadata"
Assert-Matches 'Official performance.*Fork trusted/aggressive WebGL2 scene suite results[\s\S]*-ExpectedFlagMetadata\s+\$ForkAggressiveWebGlFlags' "aggressive WebGL2 audit row renderer-specific aggressive flag metadata"
Assert-Matches "Official performance.*Stock WebGPU scene suite results[\s\S]*-RejectSoftwareRendering[\s\S]*-RejectGpuInstability[\s\S]*-RequireGpuMetadata[\s\S]*-RequireFrameTimes" "stock WebGPU audit row strict GPU and frame-time validation"
Assert-Matches 'Official performance.*Stock WebGPU scene suite results[\s\S]*-ExpectedChromiumRevision\s+\$ExpectedChromiumRevision' "stock WebGPU audit row expected Chromium revision"
Assert-Matches 'Official performance.*Stock WebGPU scene suite results[\s\S]*-ExpectedBrowser\s+\(Resolve-RepoPath "src\\out\\ReleaseBaseline\\content_shell\.exe"\)' "stock WebGPU audit row expected browser executable"
Assert-Matches 'Official performance.*Stock WebGPU scene suite results[\s\S]*-ExpectedFlagMetadata\s+\$BrowserModeFlags' "stock WebGPU audit row browser-mode flag metadata"
Assert-Matches "Official performance.*Fork WebGPU scene suite results[\s\S]*-RejectSoftwareRendering[\s\S]*-RejectGpuInstability[\s\S]*-RequireGpuMetadata[\s\S]*-RequireFrameTimes" "fork WebGPU audit row strict GPU and frame-time validation"
Assert-Matches 'Official performance.*Fork WebGPU scene suite results[\s\S]*-ExpectedChromiumRevision\s+\$ExpectedChromiumRevision' "fork WebGPU audit row expected Chromium revision"
Assert-Matches 'Official performance.*Fork WebGPU scene suite results[\s\S]*-ExpectedBrowser\s+\(Resolve-RepoPath "src\\out\\ReleaseViewerDefault\\content_shell\.exe"\)' "fork WebGPU audit row expected browser executable"
Assert-Matches 'Official performance.*Fork WebGPU scene suite results[\s\S]*-ExpectedFlagMetadata\s+\$ForkDefaultFlags' "fork WebGPU audit row viewer flag metadata"
Assert-Matches 'Official performance.*Fork trusted/aggressive WebGPU scene suite results[\s\S]*-ExpectedFlagMetadata\s+\$ForkAggressiveWebGpuFlags' "aggressive WebGPU audit row manifest-derived aggressive flag metadata"
Assert-Matches "official-comparison-manifest\.json[\s\S]*ExpectedMeasuredSeconds[\s\S]*Manifest\.options\.duration" "official manifest duration feeds audit suite validation"
Assert-Matches "official-comparison-manifest\.json[\s\S]*ExpectedWarmupSeconds[\s\S]*Manifest\.options\.warmup" "official manifest warmup feeds audit suite validation"
Assert-Matches 'resource_warmup_enabled=\$ResourceWarmupEnabled' "official audit rows include resource-warmup enabled metadata"
Assert-Matches 'resource_warmup_prerender_frames=\$ResourceWarmupPrerenderFrames' "official audit rows include resource-warmup prerender metadata"
Assert-Matches "viewer_defer_webgpu_pipeline_flush=false" "official audit rows require WebGPU pipeline-flush defer metadata to be explicitly false by default"
Assert-Matches "viewer_defer_webgpu_queue_flush=false" "official audit rows require WebGPU queue-flush defer metadata to be explicitly false by default"
Assert-Matches "viewer_defer_webgpu_submit_flush=false" "official audit rows require WebGPU submit-flush defer metadata to be explicitly false by default"
Assert-Matches "viewer_reject_webgpu_cpu_texture_fallback=false" "official audit rows require WebGPU CPU-fallback rejection metadata to be explicitly false by default"
Assert-Matches "viewer_cache_webgpu_bind_group_layouts=false" "official audit rows require WebGPU bind-group-layout cache metadata to be explicitly false by default"
Assert-Matches "viewer_skip_webgpu_command_labels=false" "official audit rows require WebGPU command-label skip metadata to be explicitly false by default"
Assert-Matches "viewer_trace_webgpu_queue=false" "official audit rows require WebGPU queue-trace metadata to be explicitly false by default"
Assert-Matches 'OfficialAggressiveWebGpuExpectedFlags[\s\S]*expected_flag_metadata[\s\S]*aggressive_webgpu' "official aggressive WebGPU suite row can use manifest-recorded source/upload fast-path metadata"
Assert-Matches "Invoke-OfficialManifestBenchmarkSuiteValidation" "official manifest validates exact result-file suites"
Assert-Matches "Official comparison manifest[\s\S]*suite validation failed" "official manifest row rejects exact-suite semantic validation failures"
Assert-Matches "benchmark suites semantically validated" "official manifest done row records semantic benchmark suite validation"
Assert-Matches "Invoke-CandidateSpeedupClaimGate" "official audit invokes candidate speedup claim analysis"
Assert-Matches "Get-TrustedMatrixCandidateManifestPathValues" "speedup claim gate considers renderer-specific trusted matrix manifests"
Assert-Matches "TrustedManifest\.result_files\.all" "speedup claim gate can add trusted matrix experiment result files"
Assert-Matches 'TrustedManifest\.chromium_revision -ne \$Manifest\.chromium_revision' "speedup claim gate rejects trusted matrix manifests from a different Chromium revision"
Assert-Matches 'OfficialPinRefreshValidation = Test-PinRefreshForCompletedManifest[\s\S]*Manifest\.generated_at[\s\S]*Manifest\.chromium_revision' "speedup claim gate rejects official manifests that predate the current Chromium pin refresh"
Assert-Matches 'TrustedPinRefreshValidation = Test-PinRefreshForCompletedManifest[\s\S]*TrustedManifest\.generated_at[\s\S]*TrustedManifest\.chromium_revision' "speedup claim gate rejects trusted matrix manifests that predate the current Chromium pin refresh"
Assert-Matches "pin refresh mismatch" "speedup claim gate reports trusted matrix pin-refresh mismatches before candidate promotion"
Assert-Matches 'TrustedManifest\.options\.duration' "speedup claim gate checks trusted matrix duration before candidate promotion"
Assert-Matches 'TrustedManifest\.options\.complexity' "speedup claim gate checks trusted matrix complexity before candidate promotion"
Assert-Matches 'SuitePromotionManifest\.options\.complexity' "speedup claim gate checks suite-promotion complexity before candidate promotion"
Assert-Matches "Invoke-TrustedMatrixBenchmarkSuiteValidation" "speedup claim gate semantically validates trusted matrix suites before candidate promotion"
Assert-Matches "missing package_dir" "speedup claim gate rejects trusted matrix candidate manifests without package evidence"
Assert-Matches "missing build-args hash" "speedup claim gate rejects trusted matrix candidate manifests without build-args hashes"
Assert-Matches "suite validation failed" "speedup claim gate reports trusted matrix suite validation failures before candidate promotion"
Assert-Matches "--requiredScene" "speedup claim gate passes required scene arguments to analyzer"
Assert-Matches "--requireCandidateRenderer" "speedup claim gate passes required renderer arguments to analyzer"
Assert-Matches 'function Invoke-CandidateSpeedupClaimGate[\s\S]*"--requirePackageSize"' "speedup claim gate requires package-size evidence in analyzer"
Assert-Matches "same-explicit-benchmark-complexity" "speedup and targeted analysis gates require explicit benchmark complexity compatibility"
Assert-Matches 'RequiredRenderers @\("webgl2", "webgpu"\)' "speedup claim gate requires both WebGL2 and WebGPU retained candidates"
Assert-Matches "Required WebGL2/WebGPU speedup claim gate[\s\S]*speedup claim gate failed" "audit row rejects missing or non-retained renderer speedup claims"
Assert-Matches 'Official performance.*Stock WebGL2 scene suite results[\s\S]*-RequirePackageSize:\$BaselinePackageRequired' "stock WebGL2 audit row inherits package-size requirement from official manifest"
Assert-Matches 'Official performance.*Fork default WebGL2 scene suite results[\s\S]*-RequirePackageSize:\$ForkPackageRequired' "fork WebGL2 audit row inherits package-size requirement from official manifest"

Write-Host "Artifact audit official suite rows enforce GPU/software/stability, frame-time samples, Chromium revision, browser executable, build-args hash, duration/warmup/complexity, resource-warmup mode, viewer flag metadata, package-size evidence, pin-refresh provenance, and WebGL2/WebGPU speedup-claim validation gates."
